def assemble(events):
    import json
    if not events or events[-1].get('type')!='done': raise ValueError('incomplete')
    return json.loads(''.join(e.get('text','') for e in events if e.get('type')=='delta'))

exercise.tests:
assert assemble([{'type':'delta','text':'{"x":1}'},{'type':'done'}])=={'x':1}
try: assemble([{'type':'delta','text':'{}'}]); assert False
except ValueError: pass

